import { describe, it, expect, beforeEach } from "vitest";
import { writeFileSync, mkdirSync } from "fs";
import { join, dirname } from "path";
import { tmpdir } from "os";
import { fileURLToPath } from "url";
import { parseNpmManifest } from "../parsers/npm.js";
import { parsePipRequirements } from "../parsers/pip.js";
import { parsePnpmLock, parseYarnLock, parseBunLock } from "../parsers/npm-locks.js";
import { parsePoetryLock, parseUvLock, parsePipfileLock } from "../parsers/pip-locks.js";
import type { Dependency } from "../parsers/npm.js";

// Fixtures were generated by the real tools (npm 10, pnpm 10, yarn 1.22, yarn 4.5,
// bun 1.2, uv, poetry 2, pipenv) from the same project:
//   npm:  lodash@4.17.15 + debug@2.6.8 (→ ms@2.0.0), dev minimist@1.2.0
//   pip:  requests==2.19.0 (→ certifi, chardet, idna, urllib3), dev py==1.4.34
const FIXTURES = join(dirname(fileURLToPath(import.meta.url)), "fixtures", "lockfiles");

function summary(deps: Dependency[]): string[] {
  return deps.map((d) => `${d.name}@${d.version}${d.isDev ? " (dev)" : ""}`).sort();
}

const NPM_EXPECTED = ["debug@2.6.8", "lodash@4.17.15", "minimist@1.2.0 (dev)", "ms@2.0.0"];

describe("npm lockfiles from real tools", () => {
  it.each([
    ["npm", "package-lock.json"],
    ["pnpm", "pnpm-lock.yaml"],
    ["yarn1", "yarn.lock"],
    ["yarn4", "yarn.lock"],
    ["bun", "bun.lock"],
  ])("%s → exact versions and dev split from %s", (dir, file) => {
    const deps = parseNpmManifest(join(FIXTURES, dir));
    expect(summary(deps)).toEqual(NPM_EXPECTED);
    expect(new Set(deps.map((d) => d.file))).toEqual(new Set([file]));
    expect(deps.every((d) => d.source === "lockfile")).toBe(true);
  });
});

describe("Python lockfiles from real tools", () => {
  it.each([
    ["uv", "uv.lock", "1.23"],
    ["poetry", "poetry.lock", "1.22"],
    ["pipenv", "Pipfile.lock", "1.23"],
  ])("%s → exact versions and dev split from %s", (dir, file, urllib3) => {
    const deps = parsePipRequirements(join(FIXTURES, dir));
    expect(summary(deps)).toEqual([
      "certifi@2026.7.22",
      "chardet@3.0.4",
      "idna@2.7",
      "py@1.4.34 (dev)",
      "requests@2.19.0",
      `urllib3@${urllib3}`,
    ]);
    expect(new Set(deps.map((d) => d.file))).toEqual(new Set([file]));
  });
});

// ── Edge cases ────────────────────────────────────────────────────────────────

describe("pnpm-lock.yaml", () => {
  it("reads the dev flag and peer suffixes of lockfile v6", () => {
    const deps = parsePnpmLock(`lockfileVersion: '6.0'
packages:
  /react-dom@18.2.0(react@18.2.0):
    dev: false
  /@types/node@20.1.0:
    dev: true
`);
    expect(summary(deps)).toEqual(["@types/node@20.1.0 (dev)", "react-dom@18.2.0"]);
  });

  it("reads lockfile v5 keys (/name/version_peer)", () => {
    const deps = parsePnpmLock(`lockfileVersion: 5.4
packages:
  /@babel/core/7.20.0:
    dev: true
  /react-dom/18.2.0_react@18.2.0:
    dev: false
`);
    expect(summary(deps)).toEqual(["@babel/core@7.20.0 (dev)", "react-dom@18.2.0"]);
  });

  it("v9: a package used by both prod and dev is prod; workspace links are skipped", () => {
    const deps = parsePnpmLock(`lockfileVersion: '9.0'
importers:
  .:
    devDependencies:
      tool:
        specifier: ^1
        version: 1.0.0
  packages/app:
    dependencies:
      shared:
        specifier: ^2
        version: 2.0.0
      local-lib:
        specifier: workspace:*
        version: link:../lib
packages: {}
snapshots:
  tool@1.0.0:
    dependencies:
      shared: 2.0.0
      only-dev: 3.0.0
  shared@2.0.0: {}
  only-dev@3.0.0: {}
`);
    expect(summary(deps)).toEqual(["only-dev@3.0.0 (dev)", "shared@2.0.0", "tool@1.0.0 (dev)"]);
  });

  it("v9: follows aliased dependencies to the real package", () => {
    const deps = parsePnpmLock(`lockfileVersion: '9.0'
importers:
  .:
    dependencies:
      sw:
        specifier: npm:string-width@4.2.3
        version: string-width@4.2.3
snapshots:
  string-width@4.2.3: {}
`);
    expect(summary(deps)).toEqual(["string-width@4.2.3"]);
  });
});

describe("yarn.lock", () => {
  it("v1: merges comma-separated descriptors and scoped names", () => {
    const deps = parseYarnLock(
      `# yarn lockfile v1

"@babel/code-frame@^7.0.0", "@babel/code-frame@^7.10.4":
  version "7.12.13"
  dependencies:
    "@babel/highlight" "^7.10.4"

"@babel/highlight@^7.10.4":
  version "7.13.10"
`,
      { dependencies: { "@babel/code-frame": "^7.10.4" } }
    );
    expect(summary(deps)).toEqual(["@babel/code-frame@7.12.13", "@babel/highlight@7.13.10"]);
  });

  it("berry: skips workspace and patch entries", () => {
    const deps = parseYarnLock(
      `__metadata:
  version: 8

"app@workspace:.":
  version: 0.0.0-use.local
  resolution: "app@workspace:."
  dependencies:
    resolve: "patch:resolve@npm%3A^1.22.0#~builtin<compat/resolve>"

"resolve@npm:^1.22.0":
  version: 1.22.8
  resolution: "resolve@npm:1.22.8"

"resolve@patch:resolve@npm%3A^1.22.0#~builtin<compat/resolve>":
  version: 1.22.8
  resolution: "resolve@patch:resolve@npm%3A1.22.8#~builtin<compat/resolve>::version=1.22.8&hash=c3c19d"
`,
      { dependencies: { resolve: "^1.22.0" } }
    );
    expect(summary(deps)).toEqual(["resolve@1.22.8"]);
  });
});

describe("bun.lock", () => {
  it("resolves a nested duplicate before the hoisted copy", () => {
    const deps = parseBunLock(`{
  "lockfileVersion": 1,
  "workspaces": { "": { "dependencies": { "a": "1" }, "devDependencies": { "@s/b": "1" } } },
  "packages": {
    "a": ["a@1.0.0", "", { "dependencies": { "c": "^2" } }, "sha"],
    "@s/b": ["@s/b@1.0.0", "", { "dependencies": { "c": "^1" } }, "sha"],
    "c": ["c@2.0.0", "", {}, "sha"],
    "@s/b/c": ["c@1.0.0", "", {}, "sha"],
    "local": ["local@workspace:packages/local"],
  }
}`);
    expect(summary(deps)).toEqual(["@s/b@1.0.0 (dev)", "a@1.0.0", "c@1.0.0 (dev)", "c@2.0.0"]);
  });
});

describe("Python lockfile edge cases", () => {
  it("poetry: legacy category and non-PyPI sources", () => {
    const deps = parsePoetryLock(`
[[package]]
name = "flask"
version = "2.0.0"
category = "main"

[[package]]
name = "pytest"
version = "7.0.0"
category = "dev"

[[package]]
name = "internal"
version = "0.1.0"
category = "main"

[package.source]
type = "git"
url = "https://example.com/internal.git"
`);
    expect(summary(deps)).toEqual(["flask@2.0.0", "pytest@7.0.0 (dev)"]);
  });

  it("uv: skips git/path sources and keeps the project out of the audit", () => {
    const deps = parseUvLock(`
version = 1

[[package]]
name = "app"
version = "0.1.0"
source = { editable = "." }
dependencies = [{ name = "Flask" }, { name = "internal" }]

[package.dev-dependencies]
dev = [{ name = "pytest" }]

[[package]]
name = "flask"
version = "2.0.0"
source = { registry = "https://pypi.org/simple" }

[[package]]
name = "internal"
version = "0.1.0"
source = { git = "https://example.com/internal.git" }

[[package]]
name = "pytest"
version = "7.0.0"
source = { registry = "https://pypi.org/simple" }
`);
    expect(summary(deps)).toEqual(["flask@2.0.0", "pytest@7.0.0 (dev)"]);
  });

  it("Pipfile.lock: a package in both sections counts as production; git entries are skipped", () => {
    const deps = parsePipfileLock(
      JSON.stringify({
        default: { six: { version: "==1.16.0" }, mylib: { git: "https://example.com/x.git" } },
        develop: { six: { version: "==1.16.0" }, pytest: { version: "==7.0.0" } },
      })
    );
    expect(summary(deps)).toEqual(["pytest@7.0.0 (dev)", "six@1.16.0"]);
  });
});

// ── Precedence and fallback ───────────────────────────────────────────────────

describe("lockfile selection", () => {
  let dir: string;
  beforeEach(() => {
    dir = join(tmpdir(), `locks-${Math.random().toString(36).slice(2)}`);
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, "package.json"), JSON.stringify({ dependencies: { lodash: "^4.0.0" } }));
  });

  it("uses a lockfile instead of package.json ranges", () => {
    writeFileSync(
      join(dir, "pnpm-lock.yaml"),
      `lockfileVersion: '9.0'
importers:
  .:
    dependencies:
      lodash:
        specifier: ^4.0.0
        version: 4.17.21
snapshots:
  lodash@4.17.21: {}
`
    );
    expect(parseNpmManifest(dir).map((d) => `${d.name}@${d.version}:${d.file}`)).toEqual([
      "lodash@4.17.21:pnpm-lock.yaml",
    ]);
  });

  it("falls back to package.json when the lockfile is unreadable", () => {
    writeFileSync(join(dir, "bun.lock"), "{ not json");
    expect(parseNpmManifest(dir).map((d) => `${d.name}@${d.version}:${d.file}`)).toEqual([
      "lodash@4.0.0:package.json",
    ]);
  });

  it("skips workspace members in package-lock.json", () => {
    writeFileSync(
      join(dir, "package-lock.json"),
      JSON.stringify({
        lockfileVersion: 3,
        packages: {
          "": { name: "root" },
          "packages/app": { name: "app", version: "1.0.0" },
          "node_modules/app": { resolved: "packages/app", link: true },
          "node_modules/lodash": { version: "4.17.21" },
        },
      })
    );
    expect(summary(parseNpmManifest(dir))).toEqual(["lodash@4.17.21"]);
  });

  it("prefers a Python lockfile over requirements.txt", () => {
    writeFileSync(join(dir, "requirements.txt"), "flask>=2.0\n");
    writeFileSync(
      join(dir, "Pipfile.lock"),
      JSON.stringify({ default: { flask: { version: "==2.3.3" } }, develop: {} })
    );
    expect(parsePipRequirements(dir).map((d) => `${d.name}@${d.version}:${d.file}`)).toEqual([
      "flask@2.3.3:Pipfile.lock",
    ]);
  });
});
